// Selos dos meios de pagamento aceitos pelo Mercado Pago na loja (Pix e cartões de crédito ou débito; Termos, "Preços
// e pagamento"). Visa, American Express e Mercado Pago: desenhos do pacote simple-icons 16.34.0 (CC0, domínio público),
// nas cores das marcas; Mastercard: os dois círculos; Pix: o símbolo oficial (o mesmo de icons.js); Elo e Hipercard, que
// o pacote não tem: o nome escrito, no mesmo selo. Só marcação.
const mark = (name, svg) => `<li class="pay-mark" title="${name}"><span class="sr-only">${name}</span>${svg}</li>`;
const glyph = (path, fill, view = '0 0 24 24') => `<svg viewBox="${view}" aria-hidden="true"><path fill="${fill}" d="${path}"/></svg>`;

